import type {ReactNode} from 'react';
import './navigation.css';
type Row={id:string;label:string;icon?:ReactNode;disabled?:boolean};
const groups:{title:string;rows:Row[]}[]=[{title:'Workspace',rows:[{id:'overview',label:'Overview',icon:'◈'},{id:'projects',label:'Projects'},{id:'reports',label:'Reports',disabled:true}]},{title:'Library',rows:[{id:'documents',label:'Documents',icon:'▤'},{id:'archive',label:'Archive'}]}];
export function Navigation({selected,onSelect,onSettings,onHelp}:{selected:string;onSelect:(id:string)=>void;onSettings:()=>void;onHelp:()=>void}){
 return <nav className="navigation" aria-label="Workspace"><div className="nav-content">{groups.map(group=><section key={group.title} aria-label={group.title}><h2>{group.title}</h2><ul>{group.rows.map(row=><li key={row.id}><button disabled={row.disabled} aria-current={selected===row.id?'page':undefined} onClick={()=>onSelect(row.id)}><span aria-hidden="true" className="nav-icon">{row.icon}</span><span>{row.label}</span>{row.disabled&&<span className="nav-unavailable">Soon</span>}</button></li>)}</ul></section>)}<section className="workspace-summary" aria-label="Workspace summary"><h2>Studio workspace</h2><p>12 projects · 4 members</p></section></div><footer><button onClick={onSettings}>Settings</button><button onClick={onHelp}>Help</button></footer></nav>;
}
